const trends = $input.item.json.trending_searches || [];

const simplified = trends.map((t, idx) => ({
  id: idx,
  query: t.query,
  search_volume: t.search_volume,
  increase_percentage: t.increase_percentage,
  categories: (t.categories || []).map(c => c.name)
}));

return [{
  json: {
    trends: simplified
  }
}];

// Saída bruta do Gemini (ajuste o caminho se necessário)
const raw = $input.first().json;
const text = raw.content.parts[0].text || '';

// Remove ```
const cleaned = text
  .replace(/```/g, '')
  .replace(/^json\s*/i, '')
  .trim();

// Faz o parse do JSON
let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    selected_query: 'python automation',
    reason_short: 'Fallback: assunto genérico de automação com Python.'
  };
}

// Garante só os campos que você vai usar
return [{
  json: {
    selected_query: parsed.selected_query || '',
    reason_short: parsed.reason_short || ''
  }
}];
